using System;using System.Linq;
namespace IdleIntelligence.Core
{
 public static class FeedbackRules
 {
  static bool Market(string action,GameState b,GameState a)=>new[]{"shop-buy","shop-video"}.Contains(action)&&(a.Rewards.hasReceipt?a.Rewards.receipt.id:0)>(b.Rewards.hasReceipt?b.Rewards.receipt.id:0);
  public static string Sound(string action,GameState b,GameState a){if(ReferenceEquals(a,b))return null;if(Market(action,b,a))return a.Rewards.receipt.hasItem?"unlock":a.Rewards.receipt.kind=="chest"?"gem-pickup":"purchase";if(action=="axiom-reset"&&a.Meta.resets>b.Meta.resets||action=="prestige"&&a.Prestige.resets>b.Prestige.resets)return "prestige";if(action!="foreground-tick"&&(a.Lifetime.milestones>b.Lifetime.milestones||a.Industry.discovered.Count(v=>v)>b.Industry.discovered.Count(v=>v)))return "unlock";if(a.Lifetime.trainingCompleted>b.Lifetime.trainingCompleted||a.Lifetime.researchCompleted>b.Lifetime.researchCompleted||a.Lifetime.analysesCompleted>b.Lifetime.analysesCompleted||a.Lifetime.itemsCrafted>b.Lifetime.itemsCrafted||a.Lifetime.forgeUpgrades>b.Lifetime.forgeUpgrades||a.Workshop.modules.Sum()>b.Workshop.modules.Sum())return "research-complete";if(new[]{"bonus-box-open","claim","claim-bonus","season-claim","achievement","claim-intro","challenge-claim"}.Contains(action)&&(a.Retention.gems>b.Retention.gems||a.Workshop.components.Sum()>b.Workshop.components.Sum()||a.Missions.season.claimed.Length>b.Missions.season.claimed.Length))return "gem-pickup";if(action=="challenge-run-complete"&&a.Challenges.Progress.stars>(b.Challenges.Main?.Challenges.Progress.stars??b.Challenges.Progress.stars))return "gem-pickup";if(new[]{"capsule-gem","capsule-video"}.Contains(action)&&a.Capsules.draws>b.Capsules.draws)return new[]{"item","jackpot"}.Contains(a.Capsules.last.kind)?"unlock":"gem-pickup";if(action=="salvage"&&a.Workshop.inventory.Length<b.Workshop.inventory.Length||action=="loot-drop"&&a.Workshop.components.Sum()>b.Workshop.components.Sum())return "gem-pickup";if(new[]{"upgrade","forge"}.Contains(action)&&a.Workshop.inventory.Any(i=>{var old=b.Workshop.inventory.FirstOrDefault(j=>j.id==i.id);return old!=null&&(old.rarity!=i.rarity||old.level!=i.level||old.forge!=i.forge);})||action=="blueprint-mastery"&&!a.Workshop.mastery.SequenceEqual(b.Workshop.mastery)||action=="fragment-conversion"&&a.Industry.conversionRevision>b.Industry.conversionRevision)return "purchase";if(new[]{"forge-queue","foundry-upgrade"}.Contains(action))return "purchase";if(action=="item-fuse"&&a.Lifetime.itemsFused>b.Lifetime.itemsFused)return "research-complete";return new[]{"buy-class","class-upgrade","buy","node","breakthrough","gem-offer","equipment-slot"}.Contains(action)?"purchase":null;}
  public static string Haptic(string action,GameState b,GameState a){if(Market(action,b,a))return a.Rewards.receipt.hasItem?"double":"short";if(ReferenceEquals(a,b))return null;if(action=="axiom-reset"&&a.Meta.resets>b.Meta.resets||action=="prestige"&&a.Prestige.resets>b.Prestige.resets)return "strong";if(action=="challenge-run-complete"&&Sound(action,b,a)=="gem-pickup"||action=="salvage"&&a.Workshop.inventory.Length<b.Workshop.inventory.Length)return "double";if(a.Lifetime.forgeUpgrades>b.Lifetime.forgeUpgrades)return "double";if(new[]{"forge-queue","foundry-upgrade"}.Contains(action))return "short";if(a.Lifetime.milestones>b.Lifetime.milestones||a.Workshop.inventory.Length>b.Workshop.inventory.Length)return "double";if(new[]{"upgrade","forge","blueprint-mastery","fragment-conversion"}.Contains(action)&&Sound(action,b,a)=="purchase")return "short";if(action=="item-fuse"&&a.Lifetime.itemsFused>b.Lifetime.itemsFused)return "double";return new[]{"buy-class","class-upgrade","buy","gem-offer","bonus-box-open","claim","claim-bonus","season-claim","achievement","claim-intro"}.Contains(action)?"short":null;}
 }
}
